    {
      "card_ids": ["C10"],
      "claim": "An OCF3-containing heterocycle with an N-benzyl motif showed meaningful rat brain uptake (0.51 %ID/g at 5 min), supporting that the query's trifluoromethoxy and benzyl-like features are compatible with BBB penetration.",
      "evidence_role": "supportive"
